WITH filtered_shipments AS (SELECT * FROM shipments WHERE YEAR(shipped_date) = 2024 OR shipped_date <= '2025-09-01'), agg AS (SELECT order_id, DATE_TRUNC('MONTH', delivered_date) delivered_month, ROUND((100 * SUM(CASE WHEN carrier = 'FedEx' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_fedex FROM filtered_shipments GROUP BY order_id, DATE_TRUNC('MONTH', delivered_date)) SELECT order_id, delivered_month, pct_fedex FROM agg WHERE pct_fedex > 34 ORDER BY order_id;
